-- Redridge Mountains: creature abilities
-- Most of the zone's creatures had no AI or ran classic rows. Redridge is the Cataclysm revamp, so port their abilities from the
-- Cataclysm data (the Blackrock orcs, the Redridge gnolls, the wildlife, the Lakeshire guards), and from the classic data where
-- Cataclysm has none (Boulderheart, the Murloc Scouts' Poisonous Stab), keeping the scripts already in place. The Venom Web Spiders
-- and Blackrock Hunters keep their classic abilities next to the Cataclysm ones, which would leave them with a single spell. Ol'
-- Gummers and Overlord Barbarius, which no reference scripts, cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '217,334,423,428,430,431,486,548,568,578,579,580,615,703,711,712,932,933,935,947,4462,7009,7013,14269,14271,14272,14273,43083,43084,43094,43106,43173,43183,43185,43327,43329,43341,43350,43363,43532,43533,43535,43775,51921';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '43041,43369';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
